<?php declare(strict_types=1); require_once __DIR__.'/lib/auth.php'; $u=require_login();$error='';$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){$old=(string)($_POST['old_password']??'');$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');try{$q=db()->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$u['id']]);$hash=(string)$q->fetchColumn();if(!password_verify($old,$hash))$error='Mật khẩu hiện tại không đúng.';elseif(strlen($pass)<8)$error='Mật khẩu mới phải có ít nhất 8 ký tự.';elseif($pass!==$confirm)$error='Mật khẩu nhập lại không khớp.';else{db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$u['id']]);$ok='Đã đổi mật khẩu thành công.';}}catch(Throwable $e){$error='Không thể đổi mật khẩu.';}} ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đổi mật khẩu</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="auth-page"><section class="auth-card"><a class="auth-brand" href="workspace.php">▶ <strong>VideoDubing AI</strong></a><h1>Đổi mật khẩu</h1><p class="hint">Tài khoản: <?=htmlspecialchars($u['email'])?></p><?php if($ok):?><div class="alert ok"><?=htmlspecialchars($ok)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="field"><label>Mật khẩu hiện tại</label><input class="input" type="password" name="old_password" required></div><div class="field"><label>Mật khẩu mới</label><input class="input" type="password" name="password" minlength="8" required></div><div class="field"><label>Nhập lại mật khẩu mới</label><input class="input" type="password" name="confirm_password" minlength="8" required></div><button class="primary" style="width:100%">ĐỔI MẬT KHẨU</button></form><p class="auth-bottom"><a href="workspace.php">← Quay lại</a></p></section></main></body></html>